export type VisualKind = 'flow' | 'parallel' | 'loop' | 'stack' | 'network' | 'compare' | 'bottleneck' | 'matrix' | 'layers'

export interface VisualBeat {
  label: string
  detail: string
  tone?: 'input' | 'work' | 'output' | 'memory'
}

export interface VisualStory {
  kind: VisualKind
  kicker: string
  title: string
  beats: VisualBeat[]
  takeaway: string
  image?: string
  imageAlt?: string
}

const b = (label: string, detail: string, tone: VisualBeat['tone'] = 'work'): VisualBeat => ({ label, detail, tone })
const family = (kicker: string) => (
  kind: VisualKind,
  title: string,
  takeaway: string,
  ...beats: VisualBeat[]
): VisualStory => ({ kind, kicker, title, takeaway, beats })

